from bisect import bisect_left, bisect_right

class TemporalProperty(list):        # holds (effective_date, value), sorted by date
    def at(self, when: date) -> Money:
        i = bisect_right([d for d, _ in self], when) - 1      # latest start <= when
        if i < 0:
            raise LookupError(f"no value effective on {when}")
        return self[i][1]

    def put(self, when: date, value: Money) -> None:
        self.insert(bisect_left([d for d, _ in self], when), (when, value))
